        ElementSymbol.S,
        ElementSymbol.P,
        ElementSymbol.F,
        ElementSymbol.Cl,
        ElementSymbol.Br,
        ElementSymbol.I,
        ElementSymbol.B,
        ElementSymbol.Si
    )

    fun specOf(symbol: ElementSymbol): ElementSpec = specs[symbol] ?: specs.getValue(ElementSymbol.C)
}
